<?php
declare(strict_types=1);
require_once __DIR__.'/../../includes/auth.php';require_once __DIR__.'/../../config/db.php';requireModuleAccess('customer_orders');
$q=$conn->query("SELECT o.*,c.customer_name,c.phone,u.full_name creator FROM customer_sales_orders o JOIN customers c ON c.id=o.customer_id LEFT JOIN users u ON u.id=o.validated_by WHERE o.status='Validated' ORDER BY o.validated_at,o.id");$orders=$q->fetchAll();$currency=(string)($conn->query("SELECT setting_value FROM settings WHERE setting_key='currency' LIMIT 1")->fetchColumn()?:'KES');$flash=$_SESSION['customer_order_flash']??'';unset($_SESSION['customer_order_flash']);
require_once __DIR__.'/../../includes/header.php';require_once __DIR__.'/../../includes/sidebar.php';?>
<main class="content"><style>.po-panel{background:#fff;border:1px solid #e2e8f0;border-radius:12px;padding:18px}.po-table{width:100%;border-collapse:collapse}.po-table th,.po-table td{padding:11px;border-bottom:1px solid #edf1f5;text-align:left;font-size:13px}.po-btn{background:#174a7e;color:#fff;padding:9px 13px;border:0;border-radius:7px;font-weight:750;cursor:pointer}.muted{color:#64748b}</style>
<h1>Pending Invoices</h1><p class="muted">Validated customer orders waiting for invoice confirmation.</p><?php if($flash):?><p class="po-panel"><?=e($flash)?></p><?php endif;?>
<section class="po-panel"><div style="overflow:auto"><table class="po-table"><thead><tr><th>Order</th><th>Validated</th><th>Customer</th><th>Total</th><th>Validated by</th><th>Action</th></tr></thead><tbody>
<?php foreach($orders as $o):?><tr><td><strong><?=e($o['order_number'])?></strong></td><td><?=e($o['validated_at'])?></td><td><?=e($o['customer_name'])?><br><small><?=e($o['phone']??'')?></small></td><td><?=e($currency)?> <?=number_format((float)$o['total_amount'],2)?></td><td><?=e($o['creator']??'Staff')?></td><td><form method="post" action="action.php" onsubmit="return confirm('Confirm this order and create its invoice? Stock will be deducted and the customer balance updated.')"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$o['id']?>"><input type="hidden" name="action" value="confirm"><button class="po-btn">Confirm &amp; Create Invoice</button></form></td></tr><?php endforeach;?>
<?php if(!$orders):?><tr><td colspan="6" class="muted">There are no orders awaiting invoice confirmation.</td></tr><?php endif;?></tbody></table></div><p><a href="index.php">Back to Customer Sales Orders</a></p></section></main><?php require_once __DIR__.'/../../includes/footer.php';?>
